 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v in counts if v != background]
    # The sparse non-background objects are endpoints; connector is color 2.
    marker = max(markers, key=lambda v: counts[v])
    out = [row[:] for row in grid]
    for r in range(h):
        positions = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == "__main__":
    test = [
        [9,9,9,9,4,9,4,4,4,9,4,4,4,9,4,4,9,9,4],
        [9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],
        [9]*19,
        [9,9,9,9,4,9,4,4,4,4,9,9,4,4,4,4,4,4,4],
        [9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,9],
        [9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],
        [9,9,9,9,4,4,9,4,9,4,4,9,9,4,9,4,9,4,4],
        [9]*19, [9]*19, [9]*19,
    ]
    result = transform(test)
    for row in result:
        print(*row)
    # Verify the same connector rule also applies when the background/marker differ.
    demo = [[1]*22 for _ in range(17)]
    for r, c in [(2,6),(2,8),(2,14),(4,6),(8,14),(9,14),(11,6),(13,6),(14,14),(15,7),(15,14)]:
        demo[r][c] = 8
    transformed = transform(demo)
    assert transformed[2][9:14] == [2,2,2,2,2]
    assert transformed[3][6] == 2 and transformed[10][14] == 2
    print('checks passed')

def _demo1_check():
